/**
 * The list footer: a summary line and previous / next page buttons. With `numbered` it shows page numbers (1 … 4
 * 5 6 … 21), with `moreLabel` a "Load more" button. The current page is a plain element marked
 * aria-current="page"; the others are buttons. All text comes in through props.
 */
import { Fragment, type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { Inline } from "../primitives/inline/inline";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { pageWindow, tpl } from "../utils";

export type PagerProps = {
  page: number;
  pages: number;
  summary: string;
  previousLabel: string;
  nextLabel: string;
  numbered?: boolean;
  pageLabel?: string;
  moreLabel?: string;
  onPage?: (page: number) => void;
  onMore?: () => void;
};

export function Pager({
  page,
  pages,
  summary,
  previousLabel,
  nextLabel,
  numbered = false,
  pageLabel,
  moreLabel,
  onPage,
  onMore,
}: PagerProps) {
  const numbers = pageWindow(page, pages);
  return (
    <Box
      className={"flex flex-wrap items-center justify-between gap-4 text-xs font-semibold text-muted-foreground"}
      data-testid="pager"
    >
      <Inline className="flex flex-wrap items-center gap-4">
        <Inline>
          {summary}
        </Inline>
      </Inline>
      <Inline className="flex flex-wrap items-center gap-2">
        {(moreLabel && (page < pages)) ? (
          <Button variant="outline" size="sm" type="button" data-testid="pager-more" onClick={() => onMore?.()}>
            {moreLabel}
          </Button>
        ) : null}
        <Button
          variant="outline"
          size="sm"
          layout="icon"
          aria-label={previousLabel}
          disabled={(page <= 1)}
          onClick={() => onPage?.((page - 1))}
        >
          <LucideIcon name="chevron-left" size={16} />
        </Button>
        {numbered ? (
          <>
            {(numbers ?? []).map((n, i) => (
              <Fragment key={(n || tpl("gap{0}", i))}>
                {(n === null) ? (
                  <Inline className="w-8 text-center">
                    {"…"}
                  </Inline>
                ) : (n === page) ? (
                  <Inline
                    className={"flex h-8 min-w-8 items-center justify-center rounded bg-foreground px-2 font-bold text-background"}
                    aria-current="page"
                    data-testid="pager-current"
                  >
                    {n}
                  </Inline>
                ) : (
                  <Button
                    variant="ghost"
                    size="sm"
                    layout="icon"
                    type="button"
                    aria-label={tpl(pageLabel, n)}
                    onClick={() => onPage?.(n)}
                  >
                    {n}
                  </Button>
                )}
              </Fragment>
            ))}
          </>
        ) : (
          <Inline className="min-w-12 text-center font-bold text-foreground">
            {page}
            {" / "}
            {pages}
          </Inline>
        )}
        <Button
          variant="outline"
          size="sm"
          layout="icon"
          aria-label={nextLabel}
          disabled={(page >= pages)}
          onClick={() => onPage?.((page + 1))}
        >
          <LucideIcon name="chevron-right" size={16} />
        </Button>
      </Inline>
    </Box>
  );
}
